/* C API of the Rust port of `extension/proot_ext_harness/`, generated by rust-anything. */
#ifndef PROOT_EXTENSIONS_H
#define PROOT_EXTENSIONS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

long long ra_fs_corrected_size(const char *path);
unsigned int ra_hf_hasprefix(const char *prefix, const char *str);
unsigned int ra_hf_mybcopy(const unsigned char *src, unsigned int num, unsigned char *dst, unsigned int dst_n);
unsigned int ra_hf_filter(int is64, const unsigned char *orig, unsigned int res, unsigned char *copy, unsigned int copy_n);

/* The same functions under `rust_anything_` names, for shadow runs. */
long long rust_anything_ra_fs_corrected_size(const char *path);
unsigned int rust_anything_ra_hf_hasprefix(const char *prefix, const char *str);
unsigned int rust_anything_ra_hf_mybcopy(const unsigned char *src, unsigned int num, unsigned char *dst, unsigned int dst_n);
unsigned int rust_anything_ra_hf_filter(int is64, const unsigned char *orig, unsigned int res, unsigned char *copy, unsigned int copy_n);

#endif /* PROOT_EXTENSIONS_H */
